#include "group_query_attention_custom_tiling.h"
#include "register/op_def_registry.h"
#include <cmath>

namespace {
inline uint64_t SafeMul(uint64_t a, uint64_t b) {
    return a * b;
}
}

namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 输入q:[B,L,H,Hd], k:[B,L,Hkv,Hd], v:[B,L,Hkv,Hd]
    const gert::Shape* q_shape = context->GetInputShape(0);
    if (q_shape->GetOriginShape().GetDimNum() != 4) {
        return ge::GRAPH_FAILED;
    }
    const gert::Shape* k_shape = context->GetInputShape(1);
    const gert::Shape* v_shape = context->GetInputShape(2);

    auto q_dims = q_shape->GetOriginShape().GetDims();
    auto k_dims = k_shape->GetOriginShape().GetDims();

    uint32_t B  = static_cast<uint32_t>(q_dims[0]);
    uint32_t L  = static_cast<uint32_t>(q_dims[1]);
    uint32_t H  = static_cast<uint32_t>(q_dims[2]);
    uint32_t Hd = static_cast<uint32_t>(q_dims[3]);
    uint32_t Hkv= static_cast<uint32_t>(k_dims[2]);

    if (H == 0 || Hkv == 0 || (H % Hkv) != 0) {
        return ge::GRAPH_FAILED;
    }
    uint32_t groupSize = H / Hkv;
    float invSqrtHd = 1.0f / std::sqrt(static_cast<float>(Hd));

    // 配置block dim（可根据L/H等调优）
    const uint32_t BLOCK_DIM = 8;
    context->SetBlockDim(BLOCK_DIM);

    GroupQueryAttentionCustomTilingData tiling;
    tiling.set_B(B);
    tiling.set_L(L);
    tiling.set_H(H);
    tiling.set_Hkv(Hkv);
    tiling.set_Hd(Hd);
    tiling.set_GroupSize(groupSize);
    tiling.set_InvSqrtHd(invSqrtHd);

    // 为注意力得分矩阵申请GM workspace: [B, H, L, L] * sizeof(float)
    uint64_t score_elems = SafeMul(SafeMul(SafeMul(static_cast<uint64_t>(B), static_cast<uint64_t>(H)),
                                           static_cast<uint64_t>(L)), static_cast<uint64_t>(L));
    uint64_t score_bytes = score_elems * sizeof(float);
    tiling.set_ScoreWorkspaceBytes(score_bytes);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // workspace: 单一块给得分矩阵
    size_t *wsSizes = context->GetWorkspaceSizes(1);
    wsSizes[0] = static_cast<size_t>(score_bytes);

    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // 输出o与q同形状: [B,L,H,Hd]
    const gert::Shape* q_shape = context->GetInputShape(0);
    gert::Shape* o_shape = context->GetOutputShape(0);
    *o_shape = *q_shape;
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputType);
    return GRAPH_SUCCESS;
}
}

